function SidebarProjectSelector({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<'button'> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : 'button';

  return (
    <Comp
      data-slot="sidebar-project-selector"
      data-sidebar="project-selector"
      className={cn(
        'text-sidebar-foreground ring-sidebar-ring hover:bg-sidebar-accent hover:text-sidebar-accent-foreground flex h-9 w-full items-center gap-2 px-2 text-sm outline-hidden transition-[width,height,padding] focus-visible:ring-2 [&>svg]:size-4 [&>svg]:shrink-0',
        'group-data-[collapsible=icon]:size-9! group-data-[collapsible=icon]:p-2!',
        '[&>span:last-child]:truncate',
        className
      )}
      {...props}
    />
  );
}

// Sidebar Search component (copy of ProjectSelector for now)
function SidebarSearch({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<'button'> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : 'button';

  return (
    <Comp
      data-slot="sidebar-search"
      data-sidebar="search"
      className={cn(
        'text-sidebar-foreground ring-sidebar-ring hover:bg-sidebar-accent hover:text-sidebar-accent-foreground flex h-9 w-full items-center gap-2 px-2 text-sm outline-hidden transition-[width,height,padding] focus-visible:ring-2 [&>svg]:size-4 [&>svg]:shrink-0',
        'group-data-[collapsible=icon]:size-9! group-data-[collapsible=icon]:p-2!',
        '[&>span:last-child]:truncate',
        className
      )}
      {...props}
    />
  );
}

// Sidebar Pages wrapper component
function SidebarPages({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="sidebar-pages"
      data-sidebar="pages"
      className={cn(
        'flex min-h-0 flex-1 flex-col gap-3 overflow-auto pb-1 group-data-[collapsible=icon]:gap-0',
        className
      )}
      {...props}
    />
  );
}

// Sidebar Section component (base for MainPages, PinnedApps, GeneralPages)
function SidebarSection({
  className,
  'data-slot': dataSlot,
  'data-sidebar': dataSidebar,
  ...props
}: React.ComponentProps<'div'> & {
  'data-slot'?: string;
  'data-sidebar'?: string;
}) {
  return (
    <div
      data-slot={dataSlot}
      data-sidebar={dataSidebar}
      className={cn('flex flex-col gap-1', className)}
      {...props}
    />
